void compress_string(const char *src, char *dest) {
    const char *p = src;
    while (*p) {
        char ch = *p;
        int count = 0;
        while (*p == ch) {
            count++;
            p++;
        }
        *dest++ = ch;
        if (count >= 10) {
            int digits = 0;
            int temp = count;
            while (temp > 0) { temp /= 10; digits++; }
            // store digits in reverse
            char buf[20];
            temp = count;
            while (temp > 0) { buf[--digits] = (temp % 10) + '0'; temp /= 10; }
            int i;
            for (i = 0; i < digits; i++) *dest++ = buf[i];
        } else {
            *dest++ = (char)(count + '0');
        }
        digits = 0; // reset, unused now but suppress warning style
    }
    *dest = '\0';
}

void compress_string(const char *src, char *dest) {
    const char *p = src;
    while (*p) {
        char ch = *p;
        int count = 0;
        while (*p == ch) {
            count++;
            p++;
        }
        *dest++ = ch;
        int tens = count / 10;
        if (tens >= 10) {
            *dest++ = (char)(tens / 10 + '0');
            tens %= 10;
        }
        if (tens > 0 || count < 10) {
            *dest++ = (char)(tens + '0');
        }
        *dest++ = (char)((count % 10) + '0');
    }
    *dest = '\0';
}

